document.querySelectorAll('input[type=date]').forEach(e=>{let d=new Date();let date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');e.min=date;e.value=date});document.querySelectorAll('form[data-demo]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();let r=f.querySelector('[role=status]');r.textContent='Simulação concluída! Nenhuma solicitação foi enviada. Em um site real, esta etapa pode ser integrada ao atendimento do negócio.';r.focus()}));const menu={principais:[['Arroz de costela','Arroz cremoso, costela desfiada, agrião e farofa crocante.',68],['Risoto da floresta','Cogumelos salteados, queijo curado e ervas frescas.',62],['Peixe da estação','Peixe grelhado, purê de mandioquinha e legumes.',74]],entradas:[['Pão da casa','Fermentação natural, manteiga de ervas e azeite.',24],['Couve-flor na brasa','Creme de castanhas, limão e ervas frescas.',32],['Croqueta de costela','Casquinha crocante e maionese de páprica. 4 unidades.',36]],doces:[['Chocolate & café','Bolo morno de chocolate com creme de café.',28],['Fruta no fogo','Abacaxi grelhado, sorvete de coco e castanhas.',26]]};function renderMenu(k){document.querySelector('#dishes').replaceChildren(...menu[k].map(([n,d,p])=>{let a=document.createElement('article');a.className='dish';let c=document.createElement('div');let h=document.createElement('h3');h.textContent=n;let t=document.createElement('p');t.textContent=d;c.append(h,t);let price=document.createElement('strong');price.textContent='R$ '+p;a.append(c,price);return a}));document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===k)))}document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>renderMenu(b.dataset.category));renderMenu('principais');